<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Billiards Game</title>
    <style>
        * { box-sizing: border-box; }
        body {
            margin: 0;
            padding: 20px;
            background: #1a1a1a;
            font-family: Arial, sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            min-height: 100vh;
        }

        #gameContainer {
            background: white;
            border-radius: 8px;
            box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
            padding: 20px;
        }

        canvas {
            display: block;
            background: linear-gradient(135deg, #2d5016 0%, #3a6b1f 100%);
            border: 20px solid #8b7355;
            border-radius: 4px;
            cursor: crosshair;
            margin-bottom: 20px;
            image-rendering: crisp-edges;
        }

        #instructions {
            background: #f0f0f0;
            padding: 15px;
            border-radius: 4px;
            margin-bottom: 15px;
            font-size: 14px;
            line-height: 1.6;
            color: #333;
        }

        #instructions strong {
            color: #2d5016;
        }

        #controls {
            display: flex;
            gap: 10px;
            justify-content: center;
        }

        button {
            padding: 10px 20px;
            font-size: 14px;
            background: #2d5016;
            color: white;
            border: none;
            border-radius: 4px;
            cursor: pointer;
            transition: background 0.2s;
            font-weight: bold;
        }

        button:hover {
            background: #3a6b1f;
        }

        button:active {
            transform: scale(0.98);
        }
    </style>
</head>
<body>
    <div id="gameContainer">
        <div id="instructions">
            <strong>How to Play:</strong><br>
            Click on the white cue ball, drag <strong>backward</strong> to aim and set power, then release to shoot.
            The farther you drag, the harder the shot. Sink balls into pockets to score.
        </div>
        <canvas id="gameCanvas" width="800" height="400"></canvas>
        <div id="controls">
            <button id="resetBtn">Reset / Rack</button>
        </div>
    </div>

    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');

        const game = {
            W: 800,
            H: 400,
            R: 8,
            friction: 0.985,
            minVelocity: 0.05,

            balls: [],
            paused: false,

            pockets: [
                { x: 0, y: 0 },
                { x: 800, y: 0 },
                { x: 800, y: 400 },
                { x: 0, y: 400 },
                { x: 400, y: 0 },
                { x: 400, y: 400 },
            ],
            pocketRadius: 14,

            reset(ballsData) {
                this.balls = ballsData.map(b => ({
                    x: b.x,
                    y: b.y,
                    vx: b.vx || 0,
                    vy: b.vy || 0,
                    cue: b.cue || false,
                    potted: false,
                }));
            },

            state() {
                return this.balls.map(b => ({
                    x: b.x,
                    y: b.y,
                    vx: b.vx,
                    vy: b.vy,
                    cue: b.cue,
                    potted: b.potted,
                }));
            },

            shoot(vx, vy) {
                const cue = this.balls.find(b => b.cue);
                if (cue) {
                    cue.vx = vx;
                    cue.vy = vy;
                }
            },

            pause() {
                this.paused = true;
            },

            resume() {
                this.paused = false;
            },

            step(dt) {
                if (this.paused || dt <= 0) return;

                for (let ball of this.balls) {
                    if (ball.potted) continue;

                    ball.x += ball.vx * dt;
                    ball.y += ball.vy * dt;

                    const speed = Math.sqrt(ball.vx * ball.vx + ball.vy * ball.vy);
                    if (speed < this.minVelocity) {
                        ball.vx = 0;
                        ball.vy = 0;
                    } else {
                        const damping = Math.pow(this.friction, dt * 60);
                        ball.vx *= damping;
                        ball.vy *= damping;
                    }

                    if (ball.x - this.R < 0) {
                        ball.x = this.R;
                        ball.vx = Math.abs(ball.vx);
                    }
                    if (ball.x + this.R > this.W) {
                        ball.x = this.W - this.R;
                        ball.vx = -Math.abs(ball.vx);
                    }
                    if (ball.y - this.R < 0) {
                        ball.y = this.R;
                        ball.vy = Math.abs(ball.vy);
                    }
                    if (ball.y + this.R > this.H) {
                        ball.y = this.H - this.R;
                        ball.vy = -Math.abs(ball.vy);
                    }

                    for (let pocket of this.pockets) {
                        const dx = ball.x - pocket.x;
                        const dy = ball.y - pocket.y;
                        if (Math.hypot(dx, dy) < this.pocketRadius) {
                            ball.potted = true;
                            ball.vx = 0;
                            ball.vy = 0;
                            break;
                        }
                    }
                }

                for (let i = 0; i < this.balls.length; i++) {
                    for (let j = i + 1; j < this.balls.length; j++) {
                        const b1 = this.balls[i];
                        const b2 = this.balls[j];

                        if (b1.potted || b2.potted) continue;

                        const dx = b2.x - b1.x;
                        const dy = b2.y - b1.y;
                        const distSq = dx * dx + dy * dy;
                        const minDistSq = (2 * this.R) * (2 * this.R);

                        if (distSq < minDistSq && distSq > 0) {
                            const dist = Math.sqrt(distSq);
                            const nx = dx / dist;
                            const ny = dy / dist;

                            const dvx = b2.vx - b1.vx;
                            const dvy = b2.vy - b1.vy;
                            const dvn = dvx * nx + dvy * ny;

                            if (dvn < 0) {
                                b1.vx += dvn * nx;
                                b1.vy += dvn * ny;
                                b2.vx -= dvn * nx;
                                b2.vy -= dvn * ny;

                                const overlap = 2 * this.R - dist;
                                const sep = (overlap / 2) + 0.01;
                                b1.x -= sep * nx;
                                b1.y -= sep * ny;
                                b2.x += sep * nx;
                                b2.y += sep * ny;
                            }
                        }
                    }
                }
            },

            render() {
                ctx.fillStyle = '#2d5016';
                ctx.fillRect(0, 0, this.W, this.H);

                ctx.fillStyle = '#0a0a0a';
                for (let pocket of this.pockets) {
                    ctx.beginPath();
                    ctx.arc(pocket.x, pocket.y, this.pocketRadius, 0, Math.PI * 2);
                    ctx.fill();
                }

                ctx.strokeStyle = '#8b7355';
                ctx.lineWidth = 8;
                ctx.strokeRect(4, 4, this.W - 8, this.H - 8);

                for (let ball of this.balls) {
                    if (ball.potted) continue;

                    ctx.fillStyle = ball.cue ? '#ffffff' : '#ff3333';
                    ctx.beginPath();
                    ctx.arc(ball.x, ball.y, this.R, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.strokeStyle = '#000000';
                    ctx.lineWidth = 0.5;
                    ctx.stroke();
                }
            }
        };

        let isDragging = false;
        let dragStart = null;
        let dragCurrent = null;

        function getMousePos(e) {
            const rect = canvas.getBoundingClientRect();
            return {
                x: e.clientX - rect.left,
                y: e.clientY - rect.top,
            };
        }

        canvas.addEventListener('mousedown', (e) => {
            const pos = getMousePos(e);
            const cue = game.balls.find(b => b.cue);

            if (!cue || cue.potted) return;

            const d = Math.hypot(pos.x - cue.x, pos.y - cue.y);
            if (d < game.R * 2.5) {
                isDragging = true;
                dragStart = pos;
                dragCurrent = pos;
                game.pause();
            }
        });

        canvas.addEventListener('mousemove', (e) => {
            if (isDragging) {
                dragCurrent = getMousePos(e);
            }
        });

        canvas.addEventListener('mouseup', () => {
            if (!isDragging || !dragStart) return;

            const cue = game.balls.find(b => b.cue);
            if (cue) {
                const dx = dragStart.x - dragCurrent.x;
                const dy = dragStart.y - dragCurrent.y;
                const dist = Math.hypot(dx, dy);

                const power = Math.min(dist / 200, 1);
                const velocity = power * 300;

                if (velocity > 1) {
                    const angle = Math.atan2(dy, dx);
                    game.shoot(Math.cos(angle) * velocity, Math.sin(angle) * velocity);
                }
            }

            isDragging = false;
            dragStart = null;
            dragCurrent = null;
            game.resume();
        });

        document.getElementById('resetBtn').addEventListener('click', () => {
            game.reset(getInitialRack());
            isDragging = false;
            dragStart = null;
            dragCurrent = null;
            game.resume();
        });

        function getInitialRack() {
            const balls = [{ x: 150, y: 200, cue: true }];

            const startX = 600;
            const startY = 200;
            const spacing = game.R * 2.1;

            for (let i = 0; i < 5; i++) {
                for (let j = 0; j <= i; j++) {
                    balls.push({
                        x: startX + i * spacing,
                        y: startY + (j - i / 2) * spacing,
                    });
                }
            }

            return balls;
        }

        window.sim = {
            W: game.W,
            H: game.H,
            R: game.R,
            reset: game.reset.bind(game),
            state: game.state.bind(game),
            step: game.step.bind(game),
            shoot: game.shoot.bind(game),
            pause: game.pause.bind(game),
            resume: game.resume.bind(game),
        };

        let lastTime = performance.now();
        function animate(currentTime) {
            const elapsed = currentTime - lastTime;
            lastTime = currentTime;

            game.step(elapsed / 1000);
            game.render();

            if (isDragging && dragStart && dragCurrent) {
                const cue = game.balls.find(b => b.cue);
                const dx = dragStart.x - dragCurrent.x;
                const dy = dragStart.y - dragCurrent.y;
                const dist = Math.hypot(dx, dy);

                ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
                ctx.lineWidth = 2;
                ctx.setLineDash([5, 5]);
                ctx.beginPath();
                ctx.moveTo(cue.x, cue.y);
                ctx.lineTo(dragCurrent.x, dragCurrent.y);
                ctx.stroke();
                ctx.setLineDash([]);

                const power = Math.min(dist / 200, 1);
                ctx.fillStyle = `rgba(255, 255, 0, ${0.3 + power * 0.5})`;
                ctx.fillRect(dragCurrent.x - 25, dragCurrent.y - 8, 50 * power, 16);
                ctx.strokeStyle = 'rgba(255, 255, 255, 0.7)';
                ctx.lineWidth = 1;
                ctx.strokeRect(dragCurrent.x - 25, dragCurrent.y - 8, 50, 16);
            }

            requestAnimationFrame(animate);
        }

        game.reset(getInitialRack());
        game.render();
        requestAnimationFrame(animate);
    </script>
</body>
</html>
